const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Orlando, Florida region
  const orlando = ee.Geometry.Point([-81.38, 28.54]);
  const region = orlando.buffer(20000); // 20km radius around Orlando

  // 1973 - Landsat 1-3 MSS
  let col1973 = ee.ImageCollection('LANDSAT/LM01/C02/T1')
    .filterBounds(region)
    .filterDate('1973-01-01', '1973-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size1973 = col1973.size().getInfo();
  console.log(`1973 Images: ${size1973}`);

  if (size1973 === 0) {
    // Try Landsat 2 or 3
    col1973 = ee.ImageCollection('LANDSAT/LM02/C02/T1')
      .filterBounds(region)
      .filterDate('1973-01-01', '1975-12-31')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    size1973 = col1973.size().getInfo();
    console.log(`1973 Images (extended): ${size1973}`);

    if (size1973 === 0) {
      console.log('No data for 1973');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 2014 - Landsat 8 OLI
  let col2014 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate('2014-01-01', '2014-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size2014 = col2014.size().getInfo();
  console.log(`2014 Images: ${size2014}`);

  if (size2014 === 0) {
    console.log('No data for 2014');
    console.log('<answer>C1</answer>');
    return;
  }

  // Process 1973 data - MSS bands (green, red, NIR1, NIR2)
  const img1973 = col1973.median();
  const ndvi1973 = img1973.normalizedDifference(['SR_B3', 'SR_B2']); // NIR1, Red for MSS
  const urban1973 = ndvi1973.lt(0.2); // Low NDVI indicates urban

  // Process 2014 data - OLI bands
  const img2014 = col2014.median();
  const ndvi2014 = img2014.normalizedDifference(['SR_B5', 'SR_B4']); // NIR, Red for OLI
  const urban2014 = ndvi2014.lt(0.2); // Low NDVI indicates urban

  // Calculate urban area (pixel count)
  const count1973 = urban1973.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('SR_B2').getInfo();

  const count2014 = urban2014.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('SR_B4').getInfo();

  console.log(`1973 Urban pixels: ${count1973}`);
  console.log(`2014 Urban pixels: ${count2014}`);

  // Validation
  if (count1973 === null || count2014 === null || 
      count1973 === undefined || count2014 === undefined) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  if (count1973 === 0 && count2014 === 0) {
    console.log('No valid urban pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // Compare urban area
  const increase = count2014 > count1973;
  const percentChange = ((count2014 - count1973) / count1973 * 100).toFixed(2);
  console.log(`Urban area change: ${percentChange}%`);

  if (increase) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
